@IsTest private class ReadOnlyDeleteProbe61Test {
 @IsTest static void observe() {
  List<Account> rows=new List<Account>{new Account(Name='First'),new Account(Name='Second')}; insert rows;
  Set<Id> ids=new Map<Id,Account>(rows).keySet(); Account trashed=new Account(Name='Trashed');insert trashed;delete trashed;
  Map<String,Object> answer=new Map<String,Object>();
  answer.put('initialMode',String.valueOf(System.getApplicationReadWriteMode()));
  Test.startTest(); Test.setReadOnlyApplicationMode(true);
  answer.put('readOnlyMode',String.valueOf(System.getApplicationReadWriteMode()));
  try {
   List<Database.DeleteResult> results=Database.delete(rows,false);
   List<Object> outputs=new List<Object>();
   for(Database.DeleteResult r:results){List<Object> errors=new List<Object>(); for(Database.Error e:r.getErrors()){errors.add(new Map<String,Object>{'status'=>String.valueOf(e.getStatusCode()),'message'=>e.getMessage(),'fields'=>e.getFields()});} outputs.add(new Map<String,Object>{'success'=>r.isSuccess(),'idPresent'=>r.getId()!=null,'errors'=>errors});}
   answer.put('deleteResults',outputs);
  } catch(Exception e){answer.put('deleteExceptionType',e.getTypeName());answer.put('deleteExceptionMessage',e.getMessage());}
  answer.put('remainingReadOnly',[SELECT COUNT() FROM Account WHERE Id IN :ids]);
  Account fresh=new Account(Name='Blocked');Database.SaveResult ir=Database.insert(fresh,false);answer.put('insert',summary(ir.isSuccess(),ir.getId(),ir.getErrors()));
  Database.SaveResult ur=Database.update(new Account(Id=rows[0].Id,Name='Changed'),false);answer.put('update',summary(ur.isSuccess(),ur.getId(),ur.getErrors()));
  Database.UpsertResult upr=Database.upsert(new Account(Id=rows[1].Id,Name='Changed'),false);answer.put('upsert',summary(upr.isSuccess(),upr.getId(),upr.getErrors()));
  Database.UndeleteResult unr=Database.undelete(trashed,false);answer.put('undelete',summary(unr.isSuccess(),unr.getId(),unr.getErrors()));
  answer.put('namesUnchanged',[SELECT COUNT() FROM Account WHERE Id IN :ids AND Name!='Changed']);
  try{delete rows;answer.put('statementUnexpectedSuccess',true);}catch(Exception e){answer.put('statement',new Map<String,Object>{'type'=>e.getTypeName(),'isDmlException'=>e instanceof DmlException,'maintenanceMessage'=>e.getMessage().contains('INSERT_UPDATE_DELETE_NOT_ALLOWED_DURING_MAINTENANCE')});}
  try{Database.delete(rows,true);answer.put('allOrNoneUnexpectedSuccess',true);}catch(Exception e){answer.put('allOrNone',new Map<String,Object>{'type'=>e.getTypeName(),'isDmlException'=>e instanceof DmlException,'maintenanceMessage'=>e.getMessage().contains('INSERT_UPDATE_DELETE_NOT_ALLOWED_DURING_MAINTENANCE')});}

  Test.setReadOnlyApplicationMode(false);
  answer.put('resetMode',String.valueOf(System.getApplicationReadWriteMode()));
  List<Database.DeleteResult> writable=Database.delete(rows,false); List<Boolean> successes=new List<Boolean>();for(Database.DeleteResult r:writable){successes.add(r.isSuccess());}
  answer.put('writableSuccesses',successes);answer.put('remainingWritable',[SELECT COUNT() FROM Account WHERE Id IN :ids]);
  Test.stopTest();
  System.assert(false,'READ_ONLY_RESULT|'+JSON.serialize(answer));
 }
 private static Map<String,Object> summary(Boolean success,Id idValue,Database.Error[] errors){List<Object> es=new List<Object>();for(Database.Error e:errors){es.add(new Map<String,Object>{'status'=>String.valueOf(e.getStatusCode()),'message'=>e.getMessage(),'fields'=>e.getFields()});}return new Map<String,Object>{'success'=>success,'idPresent'=>idValue!=null,'errors'=>es};}
}

